t("Telekinetic Grasp", "Grasp telequinético", "talent name")
t("Telekinetically grasp which item?", "¿Comprende telekinetically qué punto?", "_t")
t("%s telekinetically seizes: %s.", "%s se apoderan telekineticamente: %s.", "logSeen")
t("Beyond the Flesh", "Más allá de la carne", "talent name")
